    bg = grid[0][0]
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}

    candidates = []
    # Find foreground subsets having a horizontal or vertical mirror axis.
    for two_axis in range(2 * w - 1):
        sym = {(r, c) for r, c in pts if (r, two_axis - c) in pts}
        candidates.append(sym)
    for two_axis in range(2 * h - 1):
        sym = {(two_axis - r, c) for r, c in pts if (two_axis - r, c) in pts}
        candidates.append(sym)

    best = set()
    for sym in candidates:
        unseen = set(sym)
        while unseen:
            seed = unseen.pop()
            comp = {seed}
            stack = [seed]
            while stack:
                r, c = stack.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        q = (r + dr, c + dc)
                        if q in unseen:
                            unseen.remove(q)
                            comp.add(q)
                            stack.append(q)
            if len(comp) > len(best):
                best = comp

    return [[grid[r][c] if (r, c) in best else bg for c in range(w)] for r in range(h)]
