    bg = grid[0][0]

    # Split the input into panels separated by solid non-background columns.
    separators = []
    for c in range(w):
        color = grid[0][c]
        if color != bg and all(grid[r][c] == color for r in range(h)):
            separators.append(c)
    bounds = [-1] + separators + [w]
    panels = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    best_result = None
    best_size = 0
    for left, right in panels:
        pts = {(r, c) for r in range(h) for c in range(left, right)
               if grid[r][c] != bg}
        largest = set()
        # Objects in this task have a vertical mirror axis; all other marks are noise.
        for axis2 in range(2 * left, 2 * right):
            symmetric = {(r, c) for r, c in pts if (r, axis2 - c) in pts}
            unseen = set(symmetric)
            while unseen:
                seed = unseen.pop()
                component = {seed}
                stack = [seed]
                while stack:
                    r, c = stack.pop()
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            q = (r + dr, c + dc)
                            if q in unseen:
                                unseen.remove(q)
                                component.add(q)
                                stack.append(q)
                if len(component) > len(largest):
                    largest = component
        if len(largest) > best_size:
            best_size = len(largest)
            best_result = [[grid[r][c] if (r, c) in largest else bg
                            for c in range(left, right)] for r in range(h)]

    return best_result
